function renderSettingsForm(){document.getElementById("setClientName").value=SHELL_DATA.settings.clientName,document.getElementById("setCashBalance").value=SHELL_DATA.settings.cashBalance,document.getElementById("setTaxPct").value=SHELL_DATA.settings.defaultTaxPct,document.getElementById("setShipping").value=SHELL_DATA.settings.defaultShippingCost;document.getElementById("settingsFeeFields").innerHTML=MARKETPLACES.map(e=>`\n    <div class="field">\n      <label for="setFee_${e.replace(/\s/g,"")}">${e} (%)</label>\n      <input type="number" id="setFee_${e.replace(/\s/g,"")}" min="0" step="0.1" value="${SHELL_DATA.settings.marketplaceFees[e]??0}" data-mk="${e}">\n    </div>`).join("")}document.addEventListener("DOMContentLoaded",async()=>{await yalcaInitPortalShell()&&(initModals(),renderSettingsForm(),document.getElementById("settingsForm").addEventListener("submit",async e=>{e.preventDefault();const t=e.target.querySelector('button[type="submit"]'),a=document.getElementById("settingsSuccess");a.classList.remove("is-visible");const s={};document.querySelectorAll("#settingsFeeFields input").forEach(e=>{s[e.dataset.mk]=parseFloat(e.value)||0});const n={client_name:document.getElementById("setClientName").value,cash_balance:parseFloat(document.getElementById("setCashBalance").value)||0,default_tax_pct:parseFloat(document.getElementById("setTaxPct").value)||0,default_shipping_cost:parseFloat(document.getElementById("setShipping").value)||0,marketplace_fees:s};t.disabled=!0,t.textContent="Salvando...";try{await yalcaUpdateSettings(n),SHELL_DATA=await yalcaFetchAll(YALCA_PROFILE),renderSettingsForm(),a.classList.add("is-visible"),setTimeout(()=>a.classList.remove("is-visible"),4e3)}catch(e){alert("Não foi possível salvar as configurações: "+e.message)}finally{t.disabled=!1,t.textContent="Salvar configurações"}}))});